DROP TABLE IF EXISTS feed_links;
CREATE TABLE `feed_links` (   `FlID` mediumint(8) unsigned NOT NULL AUTO_INCREMENT,   `FlTitle` varchar(200) NOT NULL,   `FlLink` varchar(400) NOT NULL,   `FlDescription` text NOT NULL,   `FlDate` datetime NOT NULL,   `FlAudio` varchar(200) NOT NULL DEFAULT '',   `FlText` longtext NOT NULL DEFAULT '',   `FlNfID` tinyint(3) unsigned NOT NULL,   PRIMARY KEY (`FlID`),   UNIQUE KEY `FlTitle` (`FlNfID`,`FlTitle`),   KEY `FlLink` (`FlLink`),   KEY `FlDate` (`FlDate`),   CONSTRAINT `fk_feed_links_news_feed` FOREIGN KEY (`FlNfID`) REFERENCES `news_feeds` (`NfID`) ON DELETE CASCADE ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS languages;
CREATE TABLE `languages` (   `LgID` int(11) unsigned NOT NULL AUTO_INCREMENT,   `LgUsID` int(10) unsigned DEFAULT NULL,   `LgName` varchar(40) NOT NULL,   `LgDict1URI` varchar(200) NOT NULL,   `LgDict2URI` varchar(200) DEFAULT NULL,   `LgGoogleTranslateURI` varchar(200) DEFAULT NULL,   `LgDict1PopUp` tinyint(1) unsigned NOT NULL DEFAULT 0 COMMENT 'Dictionary 1 opens in popup window',   `LgDict2PopUp` tinyint(1) unsigned NOT NULL DEFAULT 0 COMMENT 'Dictionary 2 opens in popup window',   `LgGoogleTranslatePopUp` tinyint(1) unsigned NOT NULL DEFAULT 0 COMMENT 'Translator opens in popup window',   `LgSourceLang` varchar(10) DEFAULT NULL COMMENT 'Source language code (BCP 47, e.g., ja, de)',   `LgTargetLang` varchar(10) DEFAULT NULL COMMENT 'Target language code (BCP 47, e.g., en)',   `LgExportTemplate` varchar(1000) DEFAULT NULL,   `LgTextSize` smallint(5) unsigned NOT NULL DEFAULT 100,   `LgCharacterSubstitutions` varchar(500) NOT NULL DEFAULT '',   `LgRegexpSplitSentences` varchar(500) NOT NULL DEFAULT '.!?',   `LgExceptionsSplitSentences` varchar(500) NOT NULL DEFAULT '',   `LgRegexpWordCharacters` varchar(500) NOT NULL DEFAULT 'a-zA-ZÀ-ÖØ-öø-ȳ',   `LgParserType` varchar(50) DEFAULT NULL,   `LgLemmatizerType` varchar(20) DEFAULT 'dictionary',   `LgRemoveSpaces` tinyint(1) unsigned NOT NULL DEFAULT 0,   `LgSplitEachChar` tinyint(1) unsigned NOT NULL DEFAULT 0,   `LgRightToLeft` tinyint(1) unsigned NOT NULL DEFAULT 0,   `LgTTSVoiceAPI` varchar(200) NOT NULL DEFAULT '',   `LgShowRomanization` tinyint(1) unsigned NOT NULL DEFAULT 0,   `LgLocalDictMode` tinyint(1) unsigned NOT NULL DEFAULT 0 COMMENT 'Local dictionary mode: 0=online only, 1=local first, 2=local only, 3=combined',   `LgPiperVoiceId` varchar(100) DEFAULT NULL COMMENT 'Piper TTS voice ID for this language (e.g., en_US-lessac-medium)',   PRIMARY KEY (`LgID`),   UNIQUE KEY `LgName` (`LgName`),   KEY `LgUsID` (`LgUsID`),   CONSTRAINT `fk_languages_user` FOREIGN KEY (`LgUsID`) REFERENCES `users` (`UsID`) ON DELETE CASCADE ) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS word_occurrences;
CREATE TABLE `word_occurrences` (   `Ti2WoID` mediumint(8) unsigned DEFAULT NULL,   `Ti2LgID` tinyint(3) unsigned NOT NULL,   `Ti2TxID` smallint(5) unsigned NOT NULL,   `Ti2SeID` mediumint(8) unsigned NOT NULL,   `Ti2Order` smallint(5) unsigned NOT NULL,   `Ti2WordCount` tinyint(3) unsigned NOT NULL,   `Ti2Text` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,   PRIMARY KEY (`Ti2TxID`,`Ti2Order`,`Ti2WordCount`),   KEY `Ti2WoID` (`Ti2WoID`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;

DROP TABLE IF EXISTS news_feeds;
CREATE TABLE `news_feeds` (   `NfID` tinyint(3) unsigned NOT NULL AUTO_INCREMENT,   `NfUsID` int(10) unsigned DEFAULT NULL,   `NfLgID` tinyint(3) unsigned NOT NULL,   `NfName` varchar(40) NOT NULL,   `NfSourceURI` varchar(200) NOT NULL,   `NfArticleSectionTags` text NOT NULL,   `NfFilterTags` text NOT NULL,   `NfUpdate` int(12) unsigned NOT NULL,   `NfOptions` varchar(200) NOT NULL,   PRIMARY KEY (`NfID`),   KEY `NfUsID` (`NfUsID`),   KEY `NfLgID` (`NfLgID`),   KEY `NfUpdate` (`NfUpdate`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS sentences;
CREATE TABLE `sentences` (   `SeID` int(11) unsigned NOT NULL AUTO_INCREMENT,   `SeLgID` int(11) unsigned NOT NULL,   `SeTxID` int(11) unsigned NOT NULL,   `SeOrder` smallint(5) unsigned NOT NULL,   `SeText` mediumtext DEFAULT NULL,   `SeFirstPos` smallint(5) unsigned NOT NULL,   PRIMARY KEY (`SeID`),   KEY `SeLgID` (`SeLgID`),   KEY `SeTxID` (`SeTxID`),   KEY `SeOrder` (`SeOrder`),   CONSTRAINT `fk_sentences_language` FOREIGN KEY (`SeLgID`) REFERENCES `languages` (`LgID`) ON DELETE CASCADE,   CONSTRAINT `fk_sentences_text` FOREIGN KEY (`SeTxID`) REFERENCES `texts` (`TxID`) ON DELETE CASCADE ) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS settings;
CREATE TABLE `settings` (   `StKey` varchar(40) NOT NULL,   `StValue` varchar(40) DEFAULT NULL,   `StUsID` int(10) unsigned NOT NULL DEFAULT 0,   PRIMARY KEY (`StKey`,`StUsID`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS tags;
CREATE TABLE `tags` (   `TgID` int(11) unsigned NOT NULL AUTO_INCREMENT,   `TgUsID` int(10) unsigned DEFAULT NULL,   `TgText` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,   `TgComment` varchar(200) NOT NULL DEFAULT '',   PRIMARY KEY (`TgID`),   UNIQUE KEY `TgText` (`TgText`),   KEY `TgUsID` (`TgUsID`),   CONSTRAINT `fk_tags_user` FOREIGN KEY (`TgUsID`) REFERENCES `users` (`UsID`) ON DELETE CASCADE ) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS text_tags;
CREATE TABLE `text_tags` (   `T2ID` smallint(5) unsigned NOT NULL AUTO_INCREMENT,   `T2UsID` int(10) unsigned DEFAULT NULL,   `T2Text` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,   `T2Comment` varchar(200) NOT NULL DEFAULT '',   PRIMARY KEY (`T2ID`),   UNIQUE KEY `T2Text` (`T2Text`),   KEY `T2UsID` (`T2UsID`),   CONSTRAINT `fk_text_tags_user` FOREIGN KEY (`T2UsID`) REFERENCES `users` (`UsID`) ON DELETE CASCADE ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS texts;
CREATE TABLE `texts` (   `TxID` int(11) unsigned NOT NULL AUTO_INCREMENT,   `TxUsID` int(10) unsigned DEFAULT NULL,   `TxBkID` smallint(5) unsigned DEFAULT NULL,   `TxChapterNum` smallint(5) unsigned DEFAULT NULL,   `TxChapterTitle` varchar(200) DEFAULT NULL,   `TxLgID` int(11) unsigned NOT NULL,   `TxTitle` varchar(200) NOT NULL,   `TxText` mediumtext NOT NULL,   `TxAnnotatedText` longtext NOT NULL DEFAULT '',   `TxAudioURI` varchar(2048) DEFAULT NULL,   `TxSourceURI` varchar(1000) DEFAULT NULL,   `TxPosition` smallint(5) DEFAULT 0,   `TxAudioPosition` float DEFAULT 0,   `TxArchivedAt` datetime DEFAULT NULL,   PRIMARY KEY (`TxID`),   KEY `TxLgID` (`TxLgID`),   KEY `TxLgIDSourceURI` (`TxSourceURI`(20),`TxLgID`),   KEY `TxUsID` (`TxUsID`),   KEY `idx_texts_book` (`TxBkID`,`TxChapterNum`),   KEY `TxArchivedAt` (`TxArchivedAt`),   CONSTRAINT `fk_texts_book` FOREIGN KEY (`TxBkID`) REFERENCES `books` (`BkID`) ON DELETE CASCADE,   CONSTRAINT `fk_texts_language` FOREIGN KEY (`TxLgID`) REFERENCES `languages` (`LgID`) ON DELETE CASCADE,   CONSTRAINT `fk_texts_user` FOREIGN KEY (`TxUsID`) REFERENCES `users` (`UsID`) ON DELETE CASCADE ) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS text_tag_map;
CREATE TABLE `text_tag_map` (   `TtTxID` smallint(5) unsigned NOT NULL,   `TtT2ID` smallint(5) unsigned NOT NULL,   PRIMARY KEY (`TtTxID`,`TtT2ID`),   KEY `TtT2ID` (`TtT2ID`),   CONSTRAINT `fk_text_tag_map_tag` FOREIGN KEY (`TtT2ID`) REFERENCES `text_tags` (`T2ID`) ON DELETE CASCADE ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS words;
CREATE TABLE `words` (   `WoID` int(11) unsigned NOT NULL AUTO_INCREMENT,   `WoUsID` int(10) unsigned DEFAULT NULL,   `WoLgID` int(11) unsigned NOT NULL,   `WoText` varchar(250) NOT NULL,   `WoTextLC` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,   `WoLemma` varchar(250) DEFAULT NULL,   `WoLemmaLC` varchar(250) DEFAULT NULL,   `WoStatus` tinyint(4) NOT NULL,   `WoTranslation` varchar(500) NOT NULL DEFAULT '*',   `WoRomanization` varchar(100) DEFAULT NULL,   `WoSentence` varchar(1000) DEFAULT NULL,   `WoNotes` varchar(1000) DEFAULT NULL,   `WoWordCount` tinyint(3) unsigned NOT NULL DEFAULT 0,   `WoCreated` timestamp NOT NULL DEFAULT current_timestamp(),   `WoStatusChanged` timestamp NOT NULL DEFAULT '1970-01-01 12:00:00',   `WoTodayScore` double NOT NULL DEFAULT 0,   `WoTomorrowScore` double NOT NULL DEFAULT 0,   `WoRandom` double NOT NULL DEFAULT 0,   PRIMARY KEY (`WoID`),   UNIQUE KEY `WoTextLCLgID` (`WoTextLC`,`WoLgID`),   KEY `WoLgID` (`WoLgID`),   KEY `WoStatus` (`WoStatus`),   KEY `WoTranslation` (`WoTranslation`(20)),   KEY `WoCreated` (`WoCreated`),   KEY `WoStatusChanged` (`WoStatusChanged`),   KEY `WoWordCount` (`WoWordCount`),   KEY `WoTodayScore` (`WoTodayScore`),   KEY `WoTomorrowScore` (`WoTomorrowScore`),   KEY `WoRandom` (`WoRandom`),   KEY `WoUsID` (`WoUsID`),   KEY `idx_words_lemma` (`WoLemmaLC`,`WoLgID`),   CONSTRAINT `fk_words_language` FOREIGN KEY (`WoLgID`) REFERENCES `languages` (`LgID`) ON DELETE CASCADE,   CONSTRAINT `fk_words_user` FOREIGN KEY (`WoUsID`) REFERENCES `users` (`UsID`) ON DELETE CASCADE ) ENGINE=InnoDB AUTO_INCREMENT=4938 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS word_tag_map;
CREATE TABLE `word_tag_map` (   `WtWoID` mediumint(8) unsigned NOT NULL,   `WtTgID` smallint(5) unsigned NOT NULL,   PRIMARY KEY (`WtWoID`,`WtTgID`),   KEY `WtTgID` (`WtTgID`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
